export const get4319bContent = (product?: Pick<Product, 'name' | 'slug' | 'specs'> | null) => {
  if (!product) return null;
  const identifiers = [product.name, product.specs?.Model, product.specs?.['Model Number'], product.slug?.replace(/-/g, ' ')].filter(Boolean).join(' ');
  return /\b4319\s*-?\s*b\b/i.test(identifiers) || product.slug === 'tfx-airwall-pro' ? WALL_MOUNT_4319B_CONTENT : null;
};

